  "claims": [
    {
      "claim_id": "gzip_default_header",
      "necessary": "yes",
      "necessity_reason": "The compression stream supports gzip output with a default header. The harness fixes initialization to the zlib wrapper, so no fuzz input can reach that output format.",
      "before": {
        "requirement": "Deflate a gzip wrapped stream with the default gzip header when gzip window bits are selected.",
        "applicability": "required",
        "harness_status": "unsat",
        "reason": "Gzip window bits select wrap 2, and initialization leaves gzhead null. The harness always uses deflateInit, which supplies MAX_WBITS and selects wrap 1.",
        "source_evidence": [
          {
            "unit_id": "u-c18e0cf3a04f36ed174d",
            "start_line": 422,
            "end_line": 449,
            "role": "primary",
            "dependency_reason": ""
          },
          {
