            "start_line": 1065,
            "end_line": 1083,
            "role": "dependency",
            "dependency_reason": "Deflate emits the default gzip header when gzhead is null."
          },
          {
            "unit_id": "u-f1f7a9f5f4a9944938e6",
            "start_line": 379,
            "end_line": 382,
            "role": "dependency",
            "dependency_reason": "deflateInit delegates to deflateInit2_ with MAX_WBITS."
          }
        ]
      },
      "after": {
        "requirement": "Deflate a gzip wrapped stream with the default gzip header when gzip window bits are selected.",
        "applicability": "required",
        "harness_status": "unsat",
        "reason": "Gzip window bits still select wrap 2. Initialization reaches deflateResetKeep, which now clears gzhead; the harness still selects wrap 1.",
        "source_evidence": [
          {
