            "start_line": 1091,
            "end_line": 1115,
            "role": "dependency",
            "dependency_reason": "Deflate writes caller supplied gzip header fields."
          }
        ]
      },
      "after": {
        "requirement": "Emit caller supplied gzip header fields on a gzip wrapped deflate stream.",
        "applicability": "required",
