    {
      "claim_id": "reset_clears_custom_header",
      "necessary": "yes",
      "necessity_reason": "The changed reset behavior affects the gzip header state used by subsequent deflate calls. A valid customized gzip stream can be reset and compressed again, but the harness has no reset sequence.",
      "before": {
        "requirement": "Discard a previously installed custom gzip header when deflateResetKeep resets the stream.",
        "applicability": "not_applicable",
        "harness_status": "not_applicable",
        "reason": "The complete pre-change reset function did not clear gzhead; the pre-change initializer set it only when creating the stream.",
        "source_evidence": [
