            "role": "dependency",
            "dependency_reason": "Before the change, gzhead was cleared during initialization."
          }
        ]
      },
      "after": {
        "requirement": "Discard a previously installed custom gzip header when deflateResetKeep resets the stream, allowing the next deflate call to emit the default gzip header.",
        "applicability": "required",
        "harness_status": "unsat",
        "reason": "Reset now clears gzhead, and deflate selects its default gzip header path afterward. The harness neither installs a custom header nor resets a stream before compressing.",
        "source_evidence": [
          {
